<script setup>
import {reactive,computed} from 'vue';import {router} from '@inertiajs/vue3';
const props=defineProps({catalog:Object,filters:Object,path:{default:'/progress'},student:Number});const form=reactive({subject:'',topic:'',difficulty:'',mode:'',from:'',to:'',...props.filters});
const topics=computed(()=>props.catalog.topics.filter(t=>!form.subject||t.subject===form.subject).map(t=>t.topic));
function apply(){router.get(props.path,{...form,...(props.student?{student:props.student}:{})},{preserveState:true})}
</script><template><form class="filterbar" @submit.prevent="apply"><label>Subject<select v-model="form.subject" @change="form.topic=''"><option value="">All</option><option v-for="s in catalog.subjects">{{s}}</option></select></label><label>Topic<select v-model="form.topic"><option value="">All</option><option v-for="t in [...new Set(topics)]">{{t}}</option></select></label><label>Difficulty<select v-model="form.difficulty"><option value="">All</option><option>Easy</option><option>Average</option><option>Difficult</option></select></label><label>Mode<select v-model="form.mode"><option value="">All</option><option value="fresh">Fresh Catch 10</option><option value="tutor">Maki Mentor</option><option value="exam">Wasabi Rush</option><option value="assigned">Assigned exams</option></select></label><label>From<input type="date" v-model="form.from"></label><label>Through<input type="date" v-model="form.to"></label><button>Apply filters</button><button type="button" class="plain" @click="router.get(path,student?{student}:{})">Reset</button></form></template>
